import {
  DODO_FIXTURE_SECRET,
  signedDodoHeaders,
} from "./helpers/dodo-fixtures";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({
  store: vi.fn(),
  process: vi.fn(),
  after: vi.fn(),
}));
vi.mock("next/server", () => ({ after: mocks.after }));
vi.mock("@/lib/billing/webhooks", () => ({ storeBillingEvent: mocks.store }));
vi.mock("@/lib/billing/lifecycle", () => ({
  processBillingEvent: mocks.process,
}));
import { POST } from "@/app/api/webhooks/dodo/route";
import { normalizeBillingEvent } from "@/lib/billing/events";

const secret = DODO_FIXTURE_SECRET;
function request(body: string, seconds = Math.floor(Date.now() / 1000)) {
  return new Request("http://localhost/api/webhooks/dodo", {
    method: "POST",
    body,
    headers: signedDodoHeaders(body, "evt_fixture", seconds),
  });
}
beforeEach(() => {
  vi.resetAllMocks();
  for (const [key, value] of Object.entries({
    DODO_PAYMENTS_ENVIRONMENT: "test_mode",
    DODO_PAYMENTS_API_KEY: "[REDACTED_SECRET]",
    DODO_PAYMENTS_WEBHOOK_KEY: secret,
    DODO_PAYMENTS_BUSINESS_ID: "bus_fixture",
    DODO_PAID_MONTHLY_PRODUCT_ID: "pdt_fixture",
    AUTH_URL: "http://localhost:3000",
  }))
    vi.stubEnv(key, value);
  vi.stubEnv("DODO_PAYMENTS_BASE_URL", "");
  vi.stubEnv("DODO_PAYMENTS_CUSTOM_HEADERS", "");
  mocks.store.mockResolvedValue({
    id: "event-id",
    state: "RECEIVED",
    subscriptionId: "sub_fixture",
    processedAt: null,
  });
  mocks.process.mockResolvedValue({});
});
afterEach(() => vi.unstubAllEnvs());

describe("Dodo webhook HTTP signature boundary using the pinned verifier", () => {
  const body = JSON.stringify({
    business_id: "bus_fixture",
    type: "subscription.active",
    timestamp: new Date().toISOString(),
    data: {},
  });
  it("verifies exact raw bytes without a user session and commits before processing", async () => {
    const raw = " \n" + body;
    expect((await POST(request(raw))).status).toBe(200);
    expect(mocks.store).toHaveBeenCalledWith(
      raw,
      JSON.parse(body),
      "evt_fixture",
    );
    expect(mocks.process).not.toHaveBeenCalled();
    await mocks.after.mock.calls[0][0]();
    expect(mocks.process).toHaveBeenCalledWith("event-id");
    expect(mocks.store.mock.invocationCallOrder[0]).toBeLessThan(
      mocks.process.mock.invocationCallOrder[0],
    );
  });
  it("rejects missing, altered, expired and future signatures before storage", async () => {
    expect(
      (
        await POST(
          new Request("http://localhost/api/webhooks/dodo", {
            method: "POST",
            body,
          }),
        )
      ).status,
    ).toBe(401);
    for (const offset of [-601, 601])
      expect(
        (await POST(request(body, Math.floor(Date.now() / 1000) + offset)))
          .status,
      ).toBe(401);
    const signed = request(body);
    const altered = new Request(signed.url, {
      method: "POST",
      headers: signed.headers,
      body: body + " ",
    });
    expect((await POST(altered)).status).toBe(401);
    expect(mocks.store).not.toHaveBeenCalled();
  });
  it("rejects another signing secret and insecure live configuration", async () => {
    vi.stubEnv(
      "DODO_PAYMENTS_WEBHOOK_KEY",
      "whsec_" + Buffer.from("another-fixture-secret").toString("base64"),
    );
    expect((await POST(request(body))).status).toBe(401);
    vi.stubEnv("DODO_PAYMENTS_ENVIRONMENT", "live_mode");
    expect((await POST(request(body))).status).toBe(503);
    expect(mocks.store).not.toHaveBeenCalled();
  });
  it("accepts a signed live event with a secure production origin", async () => {
    vi.stubEnv("DODO_PAYMENTS_ENVIRONMENT", "live_mode");
    vi.stubEnv("AUTH_URL", "https://mailloop.in");
    expect((await POST(request(body))).status).toBe(200);
    expect(mocks.store).toHaveBeenCalledOnce();
  });
  it("returns retryable storage failures, but acknowledges durable processing failures", async () => {
    mocks.store.mockRejectedValueOnce(new Error("fixture database offline"));
    expect((await POST(request(body))).status).toBe(503);
    mocks.process.mockRejectedValueOnce(new Error("fixture provider offline"));
    expect((await POST(request(body))).status).toBe(200);
    await mocks.after.mock.calls[0][0]();
  });
  it("does not reprocess processed duplicates or unsupported events", async () => {
    mocks.store
      .mockResolvedValueOnce({ id: "event-id", processedAt: new Date() })
      .mockResolvedValueOnce(null);
    expect((await POST(request(body))).status).toBe(200);
    expect((await POST(request(body))).status).toBe(200);
    expect(mocks.process).not.toHaveBeenCalled();
  });
  it("bounds raw body size", async () => {
    expect((await POST(request("x".repeat(256 * 1024 + 1)))).status).toBe(413);
    expect(mocks.store).not.toHaveBeenCalled();
  });
});

describe("payment normalization", () => {
  const envelope = (data: unknown) => ({
    business_id: "bus_fixture",
    type: "payment.succeeded",
    timestamp: new Date().toISOString(),
    data,
  });
  const data = {
    payment_id: "pay_fixture",
    customer: { customer_id: "cus_fixture", email: "[REDACTED_EMAIL]" },
    status: "succeeded",
    currency: "INR",
    total_amount: 29900,
    subscription_id: "sub_fixture",
    service_periods: [
      {
        subscription_id: "sub_fixture",
        starts_at: "2026-10-01T00:00:00Z",
        ends_at: "2026-11-01T00:00:00Z",
      },
    ],
    card_last_four: "4242",
  };
  it("stores settlement coverage without unnecessary customer/card data", () => {
    const normalized = normalizeBillingEvent(envelope(data));
    expect(normalized?.data).toMatchObject({
      kind: "payment",
      startsAt: "2026-10-01T00:00:00Z",
      endsAt: "2026-11-01T00:00:00Z",
    });
    expect(JSON.stringify(normalized)).not.toContain("[REDACTED_EMAIL]");
    expect(JSON.stringify(normalized)).not.toContain("4242");
  });
  it("never accepts active mandates, setup charges, zero payments or missing coverage as settlement", () => {
    expect(() =>
      normalizeBillingEvent(envelope({ ...data, service_periods: [] })),
    ).toThrow();
    expect(() =>
      normalizeBillingEvent(envelope({ ...data, total_amount: 0 })),
    ).toThrow();
    expect(() =>
      normalizeBillingEvent(envelope({ ...data, status: "processing" })),
    ).toThrow();
    expect(
      normalizeBillingEvent(
        envelope({ ...data, is_update_payment_method: true }),
      ),
    ).toBeNull();
    expect(
      normalizeBillingEvent(envelope({ ...data, is_multi_subscription: true })),
    ).toBeNull();
  });
});

it("does not acknowledge before the receipt is durable", async () => {
  let finish!: (value: unknown) => void;
  mocks.store.mockImplementationOnce(
    () =>
      new Promise((resolve) => {
        finish = resolve;
      }),
  );
  let acknowledged = false;
  const pending = POST(request("{}")).then((response) => {
    acknowledged = true;
    return response;
  });
  await vi.waitFor(() => expect(mocks.store).toHaveBeenCalled());
  expect(acknowledged).toBe(false);
  finish({ id: "receipt", state: "IGNORED", processedAt: new Date() });
  expect((await pending).status).toBe(200);
});
it("does not process ignored or quarantined receipts", async () => {
  for (const state of ["IGNORED", "QUARANTINED"]) {
    mocks.store.mockResolvedValueOnce({
      id: "receipt",
      state,
      processedAt: null,
    });
    expect((await POST(request("{}"))).status).toBe(200);
  }
  expect(mocks.after).not.toHaveBeenCalled();
});
it.each(["processing", "cancelled", "failed"])(
  "normalizes payment.%s as an observation",
  (status) => {
    const event = normalizeBillingEvent({
      business_id: "bus_fixture",
      type: `payment.${status}`,
      timestamp: new Date().toISOString(),
      data: {
        payment_id: "pay_fixture",
        customer: { customer_id: "cus_fixture" },
        subscription_id: "sub_fixture",
        status,
        currency: "USD",
        total_amount: 599,
      },
    });
    expect(event?.data).toMatchObject({
      kind: "payment",
      succeeded: false,
      status,
    });
  },
);
